// What has already been written, so the scout does not re-pitch it.
const rows = Array.isArray($input.first().json.data) ? $input.first().json.data : [];
const covered = rows.map((a) => ({
  title: a.title || '',
  slug: a.slug || '',
  tags: Array.isArray(a.tags) ? a.tags : [],
}));

const tagCounts = {};
for (const a of covered) for (const t of a.tags) {
  const k = String(t).toLowerCase();
  tagCounts[k] = (tagCounts[k] || 0) + 1;
}
const topTags = Object.entries(tagCounts).sort((a, b) => b[1] - a[1]).slice(0, 15);

return [{ json: {
  coveredTitles: covered.map((a) => a.title).filter(Boolean),
  coveredSlugs: covered.map((a) => a.slug).filter(Boolean),
  topTags: topTags.map(([t, n]) => t + ' (' + n + ')'),
  count: covered.length,
  today: $now.toFormat('yyyy-MM-dd'),
} }];

