const raw = String($input.first().json.output ?? '').trim();
const ctx = $('Build Coverage Context').first().json;

let parsed;
try {
  const unfenced = raw.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  const s = unfenced.indexOf('{'), e = unfenced.lastIndexOf('}');
  parsed = JSON.parse(s >= 0 && e > s ? unfenced.slice(s, e + 1) : unfenced);
} catch {
  throw new Error('Idea agent did not return valid JSON. Raw start: ' + raw.slice(0, 200));
}

const clean = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
// crude but effective: compare significant word sets, not exact strings
const sig = (s) => new Set(
  String(s).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/)
    .filter((w) => w.length > 3)
);
const overlap = (a, b) => {
  const A = sig(a), B = sig(b);
  if (!A.size || !B.size) return 0;
  let hit = 0;
  for (const w of A) if (B.has(w)) hit++;
  return hit / Math.min(A.size, B.size);
};

const ideas = (Array.isArray(parsed.ideas) ? parsed.ideas : [])
  .map((i) => ({
    title: clean(i.title),
    hook: clean(i.hook),
    whyNow: clean(i.whyNow),
    audience: clean(i.audience),
    angle: clean(i.angle),
    brief: clean(i.brief),
    tags: (Array.isArray(i.tags) ? i.tags : []).map((t) => clean(t).toLowerCase()).slice(0, 3),
  }))
  .filter((i) => i.title && i.brief)
  // drop anything too close to an existing article
  .filter((i) => !ctx.coveredTitles.some((t) => overlap(i.title, t) > 0.6))
  .slice(0, 5);

return [{ json: {
  note: clean(parsed.note),
  ideas,
  dropped: (Array.isArray(parsed.ideas) ? parsed.ideas.length : 0) - ideas.length,
  today: ctx.today,
  covered: ctx.count,
} }];

const d = $input.first().json;
const esc = (v) => String(v ?? '')
  .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');

if (!d.ideas.length) {
  return [{ json: { message: '<b>Idea scout - ' + esc(d.today) + '</b>\n\nNothing worth pitching today. ' + esc(d.note) } }];
}

const lines = [
  '<b>Idea scout - ' + esc(d.today) + '</b>',
  esc(d.note),
  '',
];

d.ideas.forEach((i, n) => {
  lines.push('<b>' + (n + 1) + '. ' + esc(i.title) + '</b>');
  lines.push(esc(i.hook));
  lines.push('<i>Why now:</i> ' + esc(i.whyNow));
  lines.push('<i>For:</i> ' + esc(i.audience));
  lines.push('<i>Your angle:</i> ' + esc(i.angle));
  lines.push('');
  // the pasteable part: send this straight back to the capture bot
  lines.push('<pre>' + esc(i.brief) + '</pre>');
  lines.push('');
});

lines.push('Copy any grey block and send it to the capture bot to turn it into a draft.');
if (d.dropped > 0) lines.push('(' + d.dropped + ' dropped as too close to something already published.)');

// Telegram caps a message at 4096 characters
let message = lines.join('\n');
if (message.length > 4000) {
  message = message.slice(0, 3900).replace(/\n[^\n]*$/, '') + '\n\n<i>Truncated. Full set is in the execution log.</i>';
}
return [{ json: { message } }];
